 st.title('Histórico de alterações')
 logs=query('''SELECT a.changed_at AS changed,p.name AS name,p.team AS team,a.day AS day,a.old_value AS old,a.new_value AS new,a.reason AS reason FROM audit a LEFT JOIN people p ON p.id=a.person_id ORDER BY a.id DESC''')
